```openscad
// Pin hinge leaf
// Print orientation: plate flat on bed, knuckles pointing up (+Z)

$fn = 64;

// ---- Plate ----
plate_len   = 50;    // plate length along X
plate_wid   = 30;    // plate width along Y
plate_thk   = 2.5;   // plate thickness along Z

// ---- Knuckles ----
knuckle_d   = 6;     // knuckle cylinder diameter
knuckle_n   = 5;     // number of equal segments along length
knuckle_z   = 3;     // height of knuckle axis above plate (z = 3)
knuckle_r   = knuckle_d / 2;
eps         = 0.5;   // cutter overshoot past faces

// ---- Pin ----
pin_d       = 2.5;   // pin hole diameter

// X position of segment i (segments centred on the plate)
function seg_x(i) = (i - (knuckle_n - 1) / 2) * plate_len / knuckle_n;

difference() {
    union() {
        // Base plate, centred in X/Y, resting on z = 0
        translate([-plate_len / 2, -plate_wid / 2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on the +Y edge (y = plate_wid / 2 = 15)
        for (i = [0 : knuckle_n - 1])
            if (i % 2 == 0)   // 1st, 3rd, 5th segments
                translate([seg_x(i), plate_wid / 2, knuckle_z])
                    cylinder(r = knuckle_r, h = plate_thk + 0.01);
    }

    // Pin hole along the knuckle axis (x varies, y = 15, z = 3)
    translate([seg_x(-1), plate_wid / 2, knuckle_z])
        rotate([0, 90, 0])
            cylinder(r = pin_d / 2, h = plate_len + 2 * eps, center = true);
}
