// Star-shaped indexing wheel
// Print orientation: flat on bed, z = 0 upward

// ---- Parameters ----
outer_r   = 35;    // outer point distance from centre
inner_r   = 17.5;  // inner point distance from centre
points    = 5;     // number of points
thickness = 4;     // plate thickness
hole_d    = 6;     // centre hole diameter
eps       = 0.5;   // cutter overshoot

$fn = 96;

// ---- Model ----
difference() {
    // Star outline (in plane), extruded
    linear_extrude(height = thickness)
        polygon(points = [
            [outer_r, 0],
            [inner_r * cos(72), inner_r * sin(72)],
            [outer_r * cos(144), outer_r * sin(144)],
            [inner_r * cos(216), inner_r * sin(216)],
            [outer_r * cos(288), outer_r * sin(288)]
        ]);

    // Centre hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = thickness + 2 * eps);
}
