    cylinder(h = part_t, r = outer_r);

    // Rim (hollow ring)
    translate([0, 0, -1])
        cylinder(h = part_t + 2, r = inner_r);

    // Hub
    translate([0, 0, -1])
        cylinder(h = part_t + 2, r = hub_r);

    // Axle hole through hub centre
    translate([0, 0, -1])
        cylinder(h = part_t + 2, d = axle_d);

    // Spokes from hub to rim
    for (i = [0 : spoke_count - 1]) {
        rotate([0, 0, start_angle + i * 360 / spoke_count])
            translate([hub_r - 0.01, -spoke_w / 2, 0])
                cube([outer_r - hub_r + 0.01, spoke_w, part_t]);
