// Tapered riser block for a beaker, with a square pocket in the top face
// Print orientation: wide base on the bed (z = 0), narrowing upward

$fn = 64;

// ---- Dimensions (mm) ----
base_size    = 100;  // bottom square side (z = 0)
top_size     = 70;   // top square side (z = block_h)
block_h      = 25;   // overall height
pocket_size  = 60;   // square pocket side (centred in top face)
pocket_depth = 5;    // square pocket depth from top face

// ---- Derived ----
eps = 0.5;           // overshoot for clean boolean cuts
overlap = 0.01;      // small overlap so the pocket doesn't reach the top face

module tapered_block() {
    // Square frustum: edges parallel to X and Y, centred on origin in XY
    rotate([90, 0, 0])
        linear_extrude(height = block_h)
            polygon([
                [-base_size / 2, -base_size / 2],
                [ base_size / 2, -base_size / 2],
                [ base_size / 2,  base_size / 2],
                [-base_size / 2,  base_size / 2]
            ]);
}

module pocket() {
    // 2D shape of the square pocket, centred on the top face
    translate([0, 0, block_h - pocket_depth])
        cube([pocket_size, pocket_size, overlap]);
}

difference() {
    tapered_block();
    pocket();
}
```

