// Tapered riser block for a beaker, with a square pocket in the top face
// Print orientation: wide base on the bed (z = 0), narrowing upward

$fn = 64;

// ---- Dimensions (mm) ----
base_size    = 100;   // bottom square side (z = 0)
top_size     = 80;    // top square side (z = block_h)
block_h      = 20;    // overall height
pocket_w     = 72;    // pocket side
pocket_depth = 8;     // pocket depth from top face
eps          = 0.5;   // overshoot for clean boolean cuts

// ---- Derived ----
pocket_top_z = block_h - pocket_depth;   // z of the pocket's top face

module base() {
    difference() {
        // Frustum body
        cylinder(h = block_h, r1 = base_size / 2, r2 = top_size / 2);
        // Square pocket, open at the top (extends past the top face)
        translate([0, 0, pocket_top_z])
            cube([pocket_w, pocket_w, pocket_depth + eps]);
    }
}

module outline() {
    // 2D profile in the X-Z plane, then extruded around the origin
    translate([0, 0, 0])
        rotate([90, 0, 0])
            linear_extrude(height = base_size)
                polygon(points = [
                    [-top_size / 2, block_h],
                    [ top_size / 2, block_h],
                    [ top_size / 2, 0],
                    [-top_size / 2, 0]
                ]);
}

union() {
    base();
    outline();
}
