    [for (i = [0 : points - 1])
        rotate([0, 0, i * 360 / points]) [outer_r, 0]],
    [for (i = [0 : points - 1])
        rotate([0, 0, i * 360 / points]) [inner_r, 0]]
);

// ---------------- Model ----------------
difference() {
    // Extrude outline (polygon expects 2D x/y; rotation applied above)
    linear_extrude(height = plate_t)
        polygon(points = 2 * points, hull = true, trace = outline);

    // Central through-hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = plate_t + 2 * eps);
}
