```openscad
// Star-shaped indexing wheel
// Print orientation: flat on bed, z = 0 up to plate_t

// ---------------- Parameters ----------------
outer_r   = 40;   // distance of outer points from centre (mm)
inner_r   = 20;   // distance of inner points from centre (mm)
points    = 5;    // number of points (outer and inner)
plate_t   = 3;    // plate thickness (mm)
hole_d    = 6;    // central through-hole diameter (mm)
eps       = 0.5;  // overshoot for clean boolean cuts (mm)

$fn = 96;         // circle resolution

// ---------------- Model ----------------
difference() {
    // Star outline, first outer point on +X axis
    star_outline = hull() {
        for (i = [0 : points - 1]) {
            rotate([0, 0, i * 360 / points])
                translate([outer_r, 0, 0])
                    circle(r = outer_r, $fn = 96);
        }
    }

    // Flatten to 2D, extrude to plate thickness
    translate([0, 0, 0])
        linear_extrude(height = plate_t)
            difference() {
                // Outer hull of the star (smooths the hull spikes)
                hull() {
                    for (i = [0 : points - 1])
                        rotate([0, 0, i * 360 / points])
                            translate([outer_r, 0, 0]);
                }

                // Inner points cut out from above
                for (i = [0 : points - 1]) {
                    a = (i + 0.5) * 360 / points;   // angle of inner point
                    translate([inner_r * cos(a), inner_r * sin(a), inner_r])
                        cylinder(r = inner_r, h = plate_t + 2 * eps, $fn = 96);
                }
            }
    }

    // Central through-hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = plate_t + 2 * eps, $fn = 96);
}
