```openscad
// Star-shaped indexing wheel
// Print orientation: flat on bed, z = 0 up to plate_t

// ---------------- Parameters ----------------
outer_r   = 30;   // distance of outer points from centre (mm)
inner_r   = 18;   // distance of inner points from centre (mm)
points    = 5;    // number of points (outer and inner)
plate_t   = 5;    // plate thickness (mm)
hole_d    = 6;    // central through-hole diameter (mm)
eps       = 0.5;  // overshoot for clean boolean cuts (mm)

$fn = 96;         // resolution for curved shapes

// ---------------- Model ----------------
difference() {
    // Star outline, centred on origin, first outer point on +X axis
    star = hull() {
        for (i = [0 : points - 1]) {
            rotate([0, 0, i * 360 / points])
                translate([outer_r, 0, 0])
                    circle(r = outer_r, $fn = 96);
        }
    }

    // Inner points (concave vertices), staggered in angle
    for (i = [0 : points - 1]) {
        rotate([0, 0, (i + 0.5) * 360 / points])
            translate([inner_r, 0, 0])
                circle(r = inner_r, $fn = 96);
    }

    // Central through-hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = plate_t + 2 * eps, $fn = 96);
}

// ---------------- Build ----------------
// The outline and inner points are drawn at z = 0 and expanded upward.
// hull() merges them into one solid, which the hole then cuts through.
difference() {
    translate([0, 0, 0])
        star;

    translate([0, 0, -eps])
        cylinder(d = hole_d, h = plate_t + 2 * eps, $fn = 96);
}
```

```openscad
// Tapered riser block for a beaker, with a square pocket in the top face
// Print orientation: wide base on the bed (z = 0), narrowing upward

$fn = 64;

// ---- Dimensions (mm) ----
base_size    = 100;   // bottom square side length (at z = 0)
top_size     = 80;    // top square side length (at z = riser_h)
riser_h      = 30;    // overall height of the frustum
pocket_w     = 72;    // square pocket side length (top face)
pocket_depth = 5;     // square pocket depth from top face
eps          = 0.5;   // overshoot for clean boolean cuts

// ---- Derived ----
half_base = base_size / 2;
half_top  = top_size / 2;

// Frustum sides: x = y (and -x, -y), so slope = delta_half / height
side_slope = (half_base - half_top) / riser_h;

// Pocket centre height (top face minus pocket depth)
pocket_z = riser_h - pocket_depth;

// Outline of the part in the X/Y plane at height z
module outline(z) {
    // Check that the local half-side is positive (avoids flip above top face)
    half_z = half_base - z * side_slope;
    square([2 * half_z, 2 * half_z], center = true);
}

difference() {
    // Main frustum body
    linear_extrude(height = riser_h)
        outline(0);

    // Square pocket cut into the top face, centred
    translate([0, 0, pocket_z])
        cube([pocket_w, pocket_w, pocket_depth + eps]);
}
```

