// ---- Cutting overlap ----
eps         = 0.5;  // extension past cut faces

difference() {
    union() {
        // Base plate
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckle segments (1st and 3rd only)
        for (i = [0 : knuckle_n - 1]) {
            x_s = knuckle_x0 + i * knuckle_pitch;
            include(x_s < knuckle_x0 + (knuckle_n - 1) * knuckle_pitch / 2)
                translate([x_s, knuckle_w - 1.5, 0])
                    cylinder(d = knuckle_d, h = plate_thk + 0.01);
        }
    }

    // Pin hole along X through every knuckle
    translate([knuckle_x0 - eps, knuckle_w - 1.5, knuckle_z])
        rotate([0, 90, 0])
            cylinder(d = pin_d, h = plate_len + 2 * eps);
}
