eps         = 0.5;  // extension of cutters past faces

// Segment centres along X (1st, 3rd, 5th used for knuckles)
function seg_c(i) = (i - 1) * plate_len / knuckle_n + plate_len / 2;

difference() {
    union() {
        // Base plate, centred in X/Y, resting on z = 0
        translate([-plate_len / 2, -plate_wid / 2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on odd segments (1st, 3rd, 5th)
        for (i = [0 : knuckle_n - 1])
            if (i % 2 == 0)
                translate([seg_c(i + 1), plate_wid / 2, 0])
                    cylinder(r = knuckle_r, h = knuckle_h);
    }

    // Pin hole along X through every knuckle
    for (i = [0 : knuckle_n - 1])
        if (i % 2 == 0)
            translate([seg_c(i + 1) - eps, plate_wid / 2, knuckle_z])
                rotate([0, 90, 0])
                    cylinder(d = pin_d, h = knuckle_d + 2 * eps);
