```openscad
// Tapered riser block for a beaker, with a square pocket in the top face
// Print orientation: wide base on the bed (z = 0), narrowing upward

$fn = 64;

// ---- Dimensions (mm) ----
base_size    = 100;   // bottom square side length (at z = 0)
top_size     = 80;    // top square side length (at z = riser_h)
riser_h      = 25;    // overall height of the frustum
pocket_size  = 70;    // square pocket side length (top face)
pocket_depth = 8;     // square pocket depth from top face
eps          = 0.5;   // overshoot for clean boolean cuts

// ---- Derived ----
pocket_floor_z = riser_h - pocket_depth;   // z of pocket bottom face

module tapered_block() {
    // Frustum built as a hull between the two square outlines.
    // The hull (convex hull) avoids coplanar-face issues that can arise
    // with linear_extrude of rotated shapes.
    hull() {
        // Bottom face, centred, edges parallel to X and Y
        translate([-base_size/2, -base_size/2, 0])
            cube([base_size, base_size, 0.01]);

        // Top face, centred, edges parallel to X and Y
        translate([-top_size/2, -top_size/2, riser_h])
            cube([top_size, top_size, 0.01]);
    }
}

module pocket() {
    // Square pocket cut into the top face, centred
    translate([-pocket_size/2, -pocket_size/2, pocket_floor_z])
        cube([pocket_size, pocket_size, pocket_depth + eps]);
}

difference() {
    tapered_block();
    pocket();
}
```

