    }

    // Inner points (concave corners), evenly spaced in angle
    for (i = [0 : points - 1]) {
        rotate([0, 0, (i + 0.5) * 360 / points])
            translate([inner_r, 0, 0])
                cube([inner_r, inner_r, plate_t + eps]);
    }

    // Central through-hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = plate_t + 2 * eps);
}
