riser_h      = 25;   // overall height of the frustum
pocket_size  = 32;   // square pocket side (centred in top face)
pocket_depth = 5;    // depth of pocket from top face downward

eps          = 0.5;  // overshoot for clean boolean cuts

// ---- Model ----
difference() {
    // Square frustum: hull between bottom and top plates
    hull() {
        translate([-base_size/2, -base_size/2, 0])
            cube([base_size, base_size, riser_h]);
        translate([-top_size/2, -top_size/2, riser_h])
            cube([top_size, top_size, 0.01]);  // thin plate at top z
    }

    // Square pocket cut into the top face
    translate([0, 0, riser_h - pocket_depth])
        cube([pocket_size, pocket_size, pocket_depth + eps]);
}
