// Spoked wheel for small sample cart
// Print orientation: flat on bed, z = 0 upward

// ---- Dimensions (mm) ----
outer_d     = 60;    // outer rim diameter
rim_w       = 4;     // rim width (radial)
hub_d       = 16;    // hub diameter
axle_d      = 5;     // axle hole diameter
spoke_w     = 5;     // spoke width (tangential)
spoke_count = 5;     // number of spokes
thickness   = 5;     // part thickness (Z)

eps         = 0.5;   // cutter overshoot
$fn         = 96;    // circle resolution

// ---- Derived ----
outer_r = outer_d / 2;
rim_r   = outer_r - rim_w;
hub_r   = hub_d / 2;

// ---- Model ----
difference() {
    union() {
        // Rim
        cylinder(h = thickness, r = outer_r);
        // Spokes
        for (i = [0 : spoke_count - 1])
            rotate([0, 0, i * 360 / spoke_count])
                translate([0, -spoke_w / 2, 0])
                    cube([outer_r, spoke_w, thickness]);
    }
    // Hub
    translate([0, 0, -eps])
        cylinder(h = thickness + 2 * eps, r = hub_r);
    // Axle hole
    translate([0, 0, -eps])
        cylinder(h = thickness + 2 * eps, d = axle_d);
}
