// Pin hinge leaf
// Print orientation: plate flat on bed, knuckles pointing up (+Z)

$fn = 64;

// ---- Plate ----
plate_len   = 60;   // plate length along X
plate_wid   = 30;   // plate width along Y
plate_thk   = 3;    // plate thickness along Z

// ---- Knuckles ----
knuckle_d   = 7;    // knuckle cylinder diameter
knuckle_z   = 3.5;  // knuckle axis height above bed (z)
knuckle_n   = 3;    // number of knuckle segments
knuckle_x0  = 0;    // first segment start (x)
knuckle_pitch = plate_len / knuckle_n; // 20 mm segment length

// ---- Pin hole ----
pin_d       = 3;    // pin hole diameter

// ---- Cutting overlap ----
eps         = 0.5;  // extension past cut faces

difference() {
    union() {
        // Base plate
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckle segments with pin holes
        for (i = [0 : knuckle_n - 1]) {
            x = knuckle_x0 + i * knuckle_pitch - knuckle_d/2;
            translate([x, knuckle_z, 0])
                difference() {
                    cylinder(d = knuckle_d, h = plate_thk + eps);
                    translate([0, 0, -eps])
                        cylinder(d = pin_d, h = plate_thk + 2*eps);
                }
        }
    }

    // Knuckle axes (extend past top face to avoid coplanar faces)
    for (i = [0 : knuckle_n - 1]) {
        x = knuckle_x0 + i * knuckle_pitch - knuckle_d/2;
