difference() {
    // Star outline, first outer point on +X axis
    hull() {
        for (i = [0 : point_n - 1])
            rotate([0, 0, i * 360 / point_n])
                translate([outer_r, 0, 0]);
    }

    // Inner points (valleys between outer points)
    for (i = [0 : point_n - 1])
        rotate([0, 0, (i + 0.5) * 360 / point_n])
            translate([inner_r, 0, 0]);

    // Central through-hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = plate_t + 2 * eps);
}
