axle_d      = 8;    // axle hole diameter
spoke_count = 6;    // number of spokes
spoke_w     = 4;    // spoke width
eps         = 0.5;  // cutter overshoot

union() {
    // Outer rim
    difference() {
        cylinder(d = outer_d, h = part_t);
        translate([0, 0, -eps])
            cylinder(d = outer_d - 2 * rim_w, h = part_t + 2 * eps);
    }

    // Hub with axle hole
    difference() {
        cylinder(d = hub_d, h = part_t);
        translate([0, 0, -eps])
            cylinder(d = axle_d, h = part_t + 2 * eps);
    }

    // Spokes from hub to rim, first along +X
    for (i = [0 : spoke_count - 1])
        rotate([0, 0, i * 360 / spoke_count])
            translate([0, -spoke_w / 2, 0])
                cube([outer_d / 2 - hub_d / 2, spoke_w, part_t]);
}
