```openscad
// Star-shaped indexing wheel
// Print orientation: flat on bed, z = 0 up to plate_t

// ---------------- Parameters ----------------
outer_r   = 40;   // distance of outer points from centre (mm)
inner_r   = 20;   // distance of inner points from centre (mm)
point_n   = 6;    // number of points (outer = inner + 180 deg)
plate_t   = 3;    // plate thickness (mm)
hole_d    = 8;    // central through-hole diameter (mm)
eps       = 0.5;  // cutter overshoot past faces (mm)
$fn       = 96;   // circle resolution

// ---------------- Model ----------------
difference() {
    // Star outline, first outer point on +X axis
    hull() {
        for (i = [0 : point_n - 1])
            rotate([0, 0, i * 360 / point_n])
                translate([outer_r, 0, 0]);
    }

    // Evenly spaced inner points (180 deg offset from outer points)
    for (i = [0 : point_n - 1])
        translate([inner_r, 0, 0])
            rotate([0, 0, i * 360 / point_n])
                difference() {
                    cylinder(h = plate_t + eps, r = eps);  // notch cutter
                    translate([outer_r - 1, 0, 0])
                        rotate([0, 0, i * 360 / point_n])
                            cylinder(h = plate_t + eps, r = eps);  // keep outer points clean
                }

    // Central through-hole
    translate([0, 0, -eps])
        cylinder(h = plate_t + 2 * eps, d = hole_d);
}
