```openscad
// Tapered riser block for a beaker, with a square pocket in the top face
// Print orientation: wide base on the bed (z = 0), narrowing upward

$fn = 64;

// ---- Dimensions (mm) ----
base_size    = 100;  // bottom square side (z = 0)
top_size     = 80;   // top square side (z = block_h)
block_h      = 20;   // overall height
pocket_size  = 70;   // square pocket side (centred in top face)
pocket_depth = 5;    // square pocket depth from top face

// ---- Derived ----
eps = 0.5;           // overshoot for clean boolean cuts
overlap = 0.01;      // small overlap so the pocket doesn't reach the top face

module tapered_block() {
    // Frustum built as a rotated cone with truncated top and bottom
    // (3D cylinder with cap end pieces, edges parallel to X and Y)
    translate([0, 0, block_h])
        rotate([90, 0, 0])
            cylinder(h = block_h, r1 = top_size / 2, r2 = base_size / 2);
    // Cap end pieces to trim the cone at exact z = block_h and z = 0
    translate([-(base_size / 2 + eps), -(base_size / 2 + eps), 0])
        cube([base_size + 2 * eps, base_size + 2 * eps, block_h + eps]);
    translate([-(top_size / 2 + eps), -(top_size / 2 + eps), block_h])
        cube([top_size + 2 * eps, top_size + 2 * eps, eps]);
}

module pocket() {
    translate([0, 0, block_h - pocket_depth])
        cube([pocket_size, pocket_size, pocket_depth + overlap]);
}

difference() {
    tapered_block();
    pocket();
}
```

