// Pin hinge leaf
// Print orientation: plate flat on bed, knuckles pointing up (+Z)

// ---------------- Parameters ----------------
plate_len   = 40;    // plate length along X (mm)
plate_wid   = 20;    // plate width along Y (mm)
plate_thk   = 2.5;   // plate thickness along Z (mm)

knuckle_d   = 6;     // knuckle cylinder diameter (mm)
knuckle_z   = 3;     // knuckle axis height above bed (mm)
knuckle_n   = 5;     // number of equal segments along X
knuckle_r   = knuckle_d / 2;                    // knuckle radius (mm)
knuckle_h   = 4;     // knuckle height above axis (mm)

pin_d       = 2.5;   // pin hole diameter (mm)
eps         = 0.5;   // cutter overshoot past faces (mm)
$fn         = 96;    // curve resolution

// ---------------- Derived ----------------
segment_len = plate_len / knuckle_n;   // 8 mm segment length
knuckle_xs  = [i * segment_len for i = [0, 2, 4]]; // 1st, 3rd, 5th segment centres

// ---------------- Model ----------------
difference() {
    union() {
        // Base plate, centred in X/Y, resting on z = 0
        translate([-plate_len / 2, -plate_wid / 2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles along +Y edge (axis at y = 10, z = 3)
        for (x = knuckle_xs)
            translate([x, plate_wid / 2, 0])
                cylinder(r = knuckle_r, h = knuckle_h + plate_thk);
    }

    // Pin hole along the common X axis through every knuckle
    for (x = knuckle_xs)
        translate([x, plate_wid / 2, 0])
            cylinder(r = pin_d / 2, h = knuckle_h + plate_thk + 2 * eps, center = true);
}
