knuckle_d   = 8;    // knuckle cylinder diameter
knuckle_z   = 4;    // knuckle axis height above bed (z)
knuckle_n   = 3;    // number of knuckle segments
knuckle_x0  = 0;    // first segment start (X)
knuckle_pitch = plate_len / knuckle_n; // 20 mm spacing

