difference() {
    union() {
        // Base plate
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckle segments with pin holes
        for (i = [0 : knuckle_n - 1]) {
            x = knuckle_x0 + i * knuckle_pitch - knuckle_d/2;
            translate([x, knuckle_z, 0])
                difference() {
                    cylinder(d = knuckle_d, h = plate_thk + eps);
                    translate([0, 0, -eps])
                        cylinder(d = pin_d, h = plate_thk + 2*eps);
                }
        }
    }

    // Remove material between knuckles along the X axis
    for (i = [0 : knuckle_n - 2]) {
        x = knuckle_x0 + (i + 1) * knuckle_pitch - knuckle_pitch/2;
        translate([x - eps, knuckle_z, 0])
            cube([knuckle_pitch, 0, plate_thk + eps]);
    }
