```openscad
// Star-shaped indexing wheel
// Print orientation: flat on bed, z = 0 up to plate_t

// ---------------- Parameters ----------------
outer_r   = 30;   // distance of outer points from centre (mm)
inner_r   = 15;   // distance of inner points from centre (mm)
point_n   = 5;    // number of points (and outer points)
plate_t   = 3;    // plate thickness (mm)
hole_d    = 6;    // central through-hole diameter (mm)
eps       = 0.5;  // cut overshoot past faces (mm)

$fn = point_n * 2;  // resolution for curved shapes

// ---------------- Outline ----------------
// Polygon of the 5-pointed star: outer point, then inner point, repeated.
// Starts with an outer point on the +X axis as specified.
module star_outline() {
    polygon(points = [
        for (i = [0 : point_n - 1])
            rotate([0, 0, i * 360 / point_n]) [
                outer_r, 0,
                inner_r * cos(180 / point_n),
                inner_r * sin(180 / point_n)
            ]
    ]);
}

// ---------------- Part ----------------
difference() {
    // Star plate, centred in XY, resting on z = 0
    linear_extrude(height = plate_t) star_outline();

    // Central through-hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = plate_t + 2 * eps);
}
