// Spoked wheel for small sample cart
// Print orientation: flat on bed, z = 0 upward

// ---- Dimensions (mm) ----
outer_d     = 60;   // outer rim diameter
rim_w       = 6;    // rim width (radial)
hub_d       = 16;   // hub diameter
axle_d      = 6;    // axle hole diameter
spoke_w     = 4;    // spoke width
spoke_count = 5;    // number of spokes
thickness   = 5;    // part thickness (Z)

eps         = 0.5;  // cutter overshoot
$fn         = 96;   // circle resolution

// ---- Derived ----
outer_r = outer_d / 2;
rim_o   = outer_r - rim_w;   // outer radius of rim ring
hub_r   = hub_d / 2;

// ---- Model ----
union() {
    // Rim
    difference() {
        cylinder(h = thickness, r = outer_r);
        translate([0, 0, -eps])
            cylinder(h = thickness + 2 * eps, r = rim_o);
    }

    // Hub (overlaps rim slightly for a clean union)
    difference() {
        translate([0, 0, -eps])
            cylinder(h = thickness + 2 * eps, r = hub_r);
        translate([0, 0, -eps])
            cylinder(h = thickness + 2 * eps, d = axle_d);
    }

    // Spokes, first along +X
    for (i = [0 : spoke_count - 1])
        rotate([0, 0, i * 360 / spoke_count])
            translate([hub_r - 0.01, -spoke_w / 2, 0])
                cube([outer_r - hub_r + 0.01, spoke_w, thickness]);
}
