    cylinder(d = outer_d, h = part_t);

    // Rim cutout (leaves ring of width rim_w)
    translate([0, 0, -1])
        cylinder(d = outer_d - 2 * rim_w, h = part_t + 2);

    // Hub
    cylinder(d = hub_d, h = part_t);

    // Axle hole through hub
    translate([0, 0, -1])
        cylinder(d = axle_d, h = part_t + 2);

    // Spokes
    for (i = [0 : spoke_count - 1]) {
        rotate([0, 0, start_angle + i * 360 / spoke_count])
            translate([hub_r - 1, -spoke_w / 2, 0])
                cube([outer_r - hub_r + 2, spoke_w, part_t]);
    }
}
